elected{border-color:#086d95;background:linear-gradient(#43b7df,#168bb5);color:#fff;box-shadow:0 3px 0 #086d95}.seat:disabled{border-color:#d9dfe0;background:#e9edee;color:#98a5a8;cursor:not-allowed;text-decoration:line-through;box-shadow:0 3px 0 #d1d7d8}.nose,.tail{position:absolute;z-index:3;left:50%;transform:translateX(-50%);font-size:8px;font-weight:900;letter-spacing:.14em;color:#0d6687}.nose{top:-26px}.tail{bottom:20px}.legend{display:flex;gap:14px;flex-wrap:wrap;margin-top:14px;color:#667d86;font-size:11px}.legend i{display:inline-block;width:10px;height:10px;border-radius:3px}
