<aside class="card checkout"><h2>Datos de quien realiza la compra</h2><p class="hint">Esta persona recibirá la confirmación. Puede viajar o comprar para otra persona.</p><label class="field">Nombre completo<input name="contact_name" required></label><label class="field">Correo electrónico<input type="email" name="contact_email" required></label><label class="field">Teléfono / WhatsApp<input name="contact_phone" required></label><label class="field">DNI o documento<input name="contact_document" required></label><div id="passengers"></div><div class="summary"><strong id="selectionCount">0 asientos seleccionados</strong><br>Total estimado: <strong id="selectionTotal">S/ 0.00</strong></div><button class="submit">Agregar al carrito</button></aside>
</div></form></main><x-public-footer/>
<script>
const selected=new Map,inputs=document.getElementById('seatInputs'),passengers=document.getElementById('passengers'),fare={{(float)$departure->fare}},buyerName=document.querySelector('[name=contact_name]'),buyerDocument=document.querySelector('[name=contact_document]');
document.querySelectorAll('.seat:not(:disabled)').forEach(b=>b.onclick=()=>{selected.has(b.dataset.id)?selected.delete(b.dataset.id):selected.set(b.dataset.id,b.dataset.code);b.classList.toggle('selected');render()});
function syncHolder(box){const card=box.closest('.passenger'),fields=card.querySelector('.passenger-fields'),name=card.querySelector('.passenger-name'),documentField=card.querySelector('.passenger-document');if(box.checked){document.querySelectorAll('.holder-toggle').forEach(other=>{if(other!==box&&other.checked){other.checked=false;syncHolder(other)}});name.value=buyerName.value;documentField.value=buyerDocument.value;fields.hidden=true}else{fields.hidden=false;name.required=true;documentField.required=true}}
function render(){inputs.innerHTML='';passengers.innerHTML='';[...selected].forEach(([id,code],i)=>{inputs.insertAdjacentHTML('beforeend',`<input type="hidden" name="seats[]" value="${id}">`);passengers.insertAdjacentHTML('beforeend',`<div class="passenger"><strong>Pasajero · asiento ${code}</strong><label class="holder-check"><input type="checkbox" class="holder-toggle" ${i===0?'checked':''}><span>La persona que realiza la compra viaja en este asiento</span></label><div class="passenger-fields"><label class="field">Nombre completo<input class="passenger-name" name="passengers[${i}][name]" required></label><label class="field">DNI o documento<input class="passenger-document" name="passengers[${i}][document]" required></label></div></div>`)});passengers.querySelectorAll('.holder-toggle').forEach(box=>{box.addEventListener('change',()=>syncHolder(box));syncHolder(box)});document.getElementById('selectionCount').textContent=`${selected.size} asiento(s) seleccionado(s)`;document.getElementById('selectionTotal').textContent=`S/ ${(selected.size*fare).toFixed(2)}`}
;[buyerName,buyerDocument].forEach(field=>field.addEventListener('input',()=>{const box=document.querySelector('.holder-toggle:checked');if(box)syncHolder(box)}));
document.getElementById('airForm').onsubmit=e=>{if(!selected.size){e.preventDefault();alert('Selecciona al menos un asiento.')}}
</script></body></html>
